=Evaluate this sales opportunity against the playbook rules.

Opportunity Details:
- Opportunity ID: {{ $('Load Opportunities from Sheet').item.json.opportunity_id }}
- Stage: {{ $('Load Opportunities from Sheet').item.json.stage }}
- Meetings Done: {{ $('Load Opportunities from Sheet').item.json.meetings_done }}
- Demo Done: {{ $('Load Opportunities from Sheet').item.json.demo_done }}
- Approval Status: {{ $('Load Opportunities from Sheet').item.json.approval_status }}
- Rep Name: {{ $('Load Opportunities from Sheet').item.json.rep_name }}

Playbook Rules:
- Rule 1: {{ $json.rule_1 }}
- Rule 2: {{ $json.rule_2 }}
- Rule 3: {{ $json.rule_3 }}
- Passing Score: {{ $json.passing_score }}

Evaluation:
- Begin with a score of 100.
- Subtract 40 when the demo is incomplete in Proposal stage.
- Subtract 30 when fewer than 2 meetings are complete.
- Subtract 30 when approval is incomplete before Negotiation stage.
- Do not return a score below 0.
- Compliance is Yes when the score meets the passing score; otherwise No.
- Risk is Low at 80 or above, Medium from 50 through 79, and High below 50.

Return five plain-text lines in this format:
Compliance: Yes or No
Missing Steps: list missing steps or None
Score: number from 0 through 100
Reason: one short sentence
Risk Level: Low, Medium, or High

parameters.jsCode:
const raw = $json;

let geminiText =
  raw.text ||
  raw.output ||
  raw.message ||
  raw.response ||
  '';

if (
  !geminiText &&
  Array.isArray(raw.candidates) &&
  raw.candidates.length > 0 &&
  raw.candidates[0] &&
  raw.candidates[0].content &&
  Array.isArray(raw.candidates[0].content.parts) &&
  raw.candidates[0].content.parts.length > 0 &&
  raw.candidates[0].content.parts[0]
) {
  geminiText = raw.candidates[0].content.parts[0].text || '';
}

if (!geminiText && typeof raw.content === 'string') {
  geminiText = raw.content;
}

if (typeof geminiText !== 'string') {
  try {
    geminiText = JSON.stringify(geminiText);
  } catch (error) {
    geminiText = String(geminiText);
  }
}

geminiText = geminiText.trim();

if (!geminiText) {
  geminiText =
    'Gemini response was empty. Available fields: ' +
    Object.keys(raw).join(', ');
}

const result = Object.assign({}, raw);
result.compliance_response = geminiText;

return [
  {
    json: result
  }
];

const text = String($json.compliance_response || '').trim();
const lines = text.split('\n');

function readValue(label) {
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].trim();
    if (line.toLowerCase().startsWith(label.toLowerCase())) {
      return line.slice(label.length).trim();
    }
  }
  return '';
}

let score = Number.parseInt(readValue('Score:'), 10);
if (!Number.isFinite(score)) {
  score = 0;
}
score = Math.min(100, Math.max(0, score));

const complianceValue = readValue('Compliance:').toLowerCase();
let isCompliant;
if (complianceValue === 'yes') {
  isCompliant = 'Yes';
} else if (complianceValue === 'no') {
  isCompliant = 'No';
} else {
  isCompliant = score >= 70 ? 'Yes' : 'No';
}

const missingSteps = readValue('Missing Steps:') || 'None';

let riskLevel = readValue('Risk Level:');
if (
  riskLevel !== 'Low' &&
  riskLevel !== 'Medium' &&
  riskLevel !== 'High'
) {
  if (score >= 80) {
    riskLevel = 'Low';
  } else if (score >= 50) {
    riskLevel = 'Medium';
  } else {
    riskLevel = 'High';
  }
}

const reason =
  readValue('Reason:') ||
  'Evaluated against playbook rules.';

let scoreCategory = 'Critical';
if (score >= 90) {
  scoreCategory = 'Excellent';
} else if (score >= 70) {
  scoreCategory = 'Good';
} else if (score >= 50) {
  scoreCategory = 'Needs Improvement';
}

const result = Object.assign({}, $json);
result.compliance_score = score;
result.is_compliant = isCompliant;
result.missing_steps = missingSteps;
result.risk_level = riskLevel;
result.reason = reason;
result.score_category = scoreCategory;
result.checked_at = new Date().toISOString();
result.raw_gemini_response = text;

return [
  {
    json: result
  }
];

